-- English 3 final module. Run seed_english3_course.sql first. Safe to run more than once.

do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'english-3';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 7, $j$Final Assessment: Literary Analysis Research Essay$j$, $j${"prompt": "Write a literary analysis research essay of at least 500 words on one author, speech, poem or movement from American literature studied in this course. Proverbs 18:15 says, The heart of the prudent getteth knowledge; and the ear of the wise seeketh knowledge. A good scholar seeks knowledge with care and shares it with honesty.\n\nPart 1: Research Question and Thesis. Choose a topic from this course, such as Franklin and the plain style, the rhetoric of the Declaration of Independence, Hawthorne and allegory, Emerson and self reliance, the freedom narratives, Lincoln's language, Realism and Regionalism, Naturalism, the Harlem Renaissance, or Modernism. Write one research question and a debatable thesis.\n\nPart 2: Sources. Identify at least one primary source (the original text, speech or poem) and at least one secondary source (a reliable article, biography or reference). Give a simple citation for each, naming the author, title, publisher or website, and date. Explain in two sentences why each source is reliable.\n\nPart 3: Essay. Write a literary analysis with an introduction (hook, background, thesis), at least three body paragraphs using the PIE pattern (point, illustration with a quotation or specific detail, explanation), and a conclusion that restates the thesis freshly and tells why it matters. Name and explain at least three literary or rhetorical techniques, such as symbol, allegory, contrast, imagery, parallelism, ethos, pathos or logos. Explain how the historical context shaped the work.\n\nPart 4: Scripture Connection. Connect one idea in your essay to a passage of Scripture in the King James Version, quoted accurately.\n\nPart 5: Presentation Plan. In a short paragraph, outline a three minute presentation of your essay, naming your opening, three key points, closing and two helpful visuals.\n\nPart 6: Revision. List two changes you made after rereading or receiving feedback, and tell how they improved your essay.", "rubric": "100 points. Part 1, research question and thesis: 10 points. Part 2, sources and citations: 10 points. Part 3, essay structure, evidence, technique analysis and context: 45 points. Part 4, Scripture connection: 7 points. Part 5, presentation plan: 10 points. Part 6, revision: 8 points. Grammar, conventions and academic voice: 10 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Final Assessment: Literary Analysis Research Essay$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 31, $j$Final Exam: English 3$j$, $j${"questions": [{"q": "The main idea of a passage is:", "options": ["The title only", "What the whole passage is mostly about", "The first word", "The longest sentence"]}, {"q": "An appeal to the speaker's credibility is called:", "options": ["Irony", "Logos", "Pathos", "Ethos"]}, {"q": "The Declaration of Independence is organized as principles, grievances and:", "options": ["A song", "A conclusion declaring independence", "A map", "A recipe"]}, {"q": "Parallelism is:", "options": ["Similar grammatical form repeated in a series", "A setting", "A kind of rhyme", "A character"]}, {"q": "An allegory has:", "options": ["No characters", "A surface story and a deeper meaning", "Only facts", "Only dates"]}, {"q": "A symbol is:", "options": ["An object that stands for a bigger idea", "A rhyme", "A type of verb", "A date"]}, {"q": "Transcendentalists such as Emerson and Thoreau valued:", "options": ["Following the crowd", "Self reliance and nature", "Only wealth", "Ignoring nature"]}, {"q": "Free verse is poetry that:", "options": ["Always rhymes", "Has no images", "Has no words", "Does not follow regular rhyme or meter"]}, {"q": "Contrast in a narrative is used to:", "options": ["List dates", "Place differences side by side to shape meaning", "Avoid the point", "Repeat the same word"]}, {"q": "A counterargument is:", "options": ["An answer to the other side", "A rhyme", "A title", "A repeated claim"]}, {"q": "Lincoln's warning in Mark 3:25 was that a house divided against itself:", "options": ["Will always win", "Cannot stand", "Is invisible", "Will prosper"]}, {"q": "Naturalism often shows characters:", "options": ["Living in fairy tales", "Struggling against forces they cannot control", "Avoiding conflict", "Controlling everything"]}, {"q": "Hemingway's iceberg theory means that:", "options": ["Stories need no people", "Everything must be said", "Most meaning lies beneath the surface", "Stories must be cold"]}, {"q": "The Harlem Renaissance was centered in:", "options": ["Harlem in New York City", "Seattle", "Dallas", "Boston"]}, {"q": "In a PIE paragraph, the three parts are:", "options": ["Place, intro and end", "Poem, idea and example", "Plot, image and ending", "Point, illustration and explanation"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: English 3$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,1,0,1,0,1,3,1,0,1,1,2,0,3}'::int[], array[$j$The main idea is the central point of the passage.$j$,$j$Ethos builds trust in the speaker.$j$,$j$The document ends by declaring the colonies free and independent.$j$,$j$Parallelism repeats a pattern to build rhythm.$j$,$j$Allegories work on two levels.$j$,$j$Symbols represent larger ideas.$j$,$j$They taught independence of thought and love of nature.$j$,$j$Free verse has no set pattern.$j$,$j$Contrast highlights differences.$j$,$j$Good arguments respond to opposing views.$j$,$j$Mark 3:25 says that house cannot stand.$j$,$j$Naturalist writers emphasize powerful outside forces.$j$,$j$Hemingway left much unsaid.$j$,$j$It flourished in Harlem in the 1920s and 1930s.$j$,$j$PIE means point, illustration, explanation.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: English 3$j$ on conflict (item_id) do nothing;
end
$seed$;
